#[cfg(test)]
#[rustfmt::skip]
mod tests {
    use super::*;

    #[test]
    fn schema_versions_agree() {
        assert_eq!(REQUIRED_SCHEMA_VERSION, GENERATED_SCHEMA_VERSION);
        assert_eq!(GENERATED_SCHEMA_VERSION, 46);
    }

    #[test]
    fn table_metadata_is_unique() {
        assert_eq!(TABLES.len(), 123);
        let mut table_names = TABLES.iter().map(|entry| entry.table).collect::<Vec<_>>();
        table_names.sort_unstable();
        table_names.dedup();
        assert_eq!(table_names.len(), TABLES.len());
        let mut model_names = TABLES.iter().map(|entry| entry.model).collect::<Vec<_>>();
        model_names.sort_unstable();
        model_names.dedup();
        assert_eq!(model_names.len(), TABLES.len());
    }
}
